{%- set CAT = ["TG","TE","SE","OA","FD","GP","OT"] -%}
{%- set CAT_FULL = {"TG":["Transport","Goods"],"TE":["Transport","Employee"],"SE":["Spares /","Engineering"],"OA":["Office /","Admin"],"FD":["Food",""],"GP":["Geeprint",""],"OT":["Other",""]} -%}
{%- set VEHICLES = ["KAP 466","KAY 635","KCB 430","KBQ 788","KBT 972"] -%}
{%- set DAYS = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"] -%}
{%- set TYPE_CODE = {"Wage":"W","Overtime":"O","Piecework":"P","Commission":"C","Loan":"L"} -%}

{#- ---------------------------------------------------------------------------
    MONEY MACRO -- the single money renderer for this document.
      none                -> nothing (caller decides blank vs dash)
      <= -0.5             -> red parentheses, e.g. (371,019)   [never a minus sign]
      >=  0.5             -> 1,234
      true zero           -> em dash
    A cell with no APPLICABLE value (e.g. the six category columns that do not
    match a voucher row's category) must stay blank -- guard it at the call
    site with {% if %}, do not pass 0.
--------------------------------------------------------------------------- -#}
{%- macro m(v) -%}
{%- if v is none -%}
{%- elif (v|float) <= -0.5 -%}<span class="neg">({{ "{:,.0f}".format(-(v|float)) }})</span>
{%- elif (v|float) >= 0.5 -%}{{ "{:,.0f}".format(v|float) }}
{%- else -%}&mdash;
{%- endif -%}
{%- endmacro -%}

{#- Running footer. Emitted once at the foot of EACH logical sheet.
    Chrome ignores @page margin boxes, so CSS counter(page) cannot work on the
    /printview -> browser-print path; the page number is therefore computed in
    Jinja from the number of sections actually rendered.
    CAVEAT: a section that overflows onto a second physical page repeats its
    own number (the footer prints once, at the end of the section's content). -#}
{%- macro pfoot(n, tot, title, wk, fl, sun_s, sat_s) -%}
<div class="pfoot"><table><tr>
  <td class="l">{{ title }} &middot; Wk {{ wk }} &middot; {{ fl }} Float &middot; {{ sun_s }} &ndash; {{ sat_s }}</td>
  <td class="r">Page {{ n }} of {{ tot }}</td>
</tr></table></div>
{%- endmacro -%}

{#- live child rows: exclude cancelled (void) so inline sums reconcile with doc.total_out -#}
{%- set VOUCH = doc.vouchers | rejectattr("cancelled") | list -%}
{#- Voucher Register prints in transaction-date order, mirroring the controller
   autosort: dated rows ascending, undated rows last keeping their order. Split
   instead of a bare sort() because comparing None to a date raises in the sandbox. -#}
{%- set VOUCH = (VOUCH | selectattr("txn_date") | sort(attribute="txn_date") | list)
                + (VOUCH | rejectattr("txn_date") | list) -%}
{%- set WAGES = doc.wages_entries | rejectattr("cancelled") | list -%}
{%- set LOANS = doc.loan_entries | rejectattr("cancelled") | list -%}
{%- set PARK = doc.parking_entries | rejectattr("cancelled") | list -%}
{%- set MISC = doc.misc_entries | rejectattr("cancelled") | list -%}

{%- set s = namespace(cat_in=0, voucher_out=0, pc=0, etr=0, used=0) -%}
{%- set s.cat_in = VOUCH | selectattr("cash_in") | sum(attribute="amount") -%}
{%- set s.voucher_out = VOUCH | rejectattr("cash_in") | sum(attribute="amount") -%}
{%- set s.pc = VOUCH | selectattr("pc_received") | list | length -%}
{%- set s.etr = VOUCH | selectattr("etr_received") | list | length -%}
{%- for v in VOUCH -%}{%- if v.voucher_no or v.recipient or (v.amount or 0) %}{% set s.used = s.used + 1 %}{% endif -%}{%- endfor -%}

{#- receipt coverage (rows with OUT spend only) -#}
{%- set rc = namespace(doc_n=0, doc_a=0, pc_n=0, pc_a=0, etr_n=0, etr_a=0, both_n=0, both_a=0, none_n=0, none_a=0) -%}
{%- for v in VOUCH -%}
  {%- if not v.cash_in and (v.amount or 0) > 0 -%}
    {%- set _amt = v.amount or 0 -%}
    {%- if v.pc_received and v.etr_received -%}
      {%- set rc.both_n = rc.both_n + 1 %}{% set rc.both_a = rc.both_a + _amt %}{% set rc.doc_n = rc.doc_n + 1 %}{% set rc.doc_a = rc.doc_a + _amt -%}
    {%- elif v.pc_received -%}
      {%- set rc.pc_n = rc.pc_n + 1 %}{% set rc.pc_a = rc.pc_a + _amt %}{% set rc.doc_n = rc.doc_n + 1 %}{% set rc.doc_a = rc.doc_a + _amt -%}
    {%- elif v.etr_received -%}
      {%- set rc.etr_n = rc.etr_n + 1 %}{% set rc.etr_a = rc.etr_a + _amt %}{% set rc.doc_n = rc.doc_n + 1 %}{% set rc.doc_a = rc.doc_a + _amt -%}
    {%- else -%}
      {%- set rc.none_n = rc.none_n + 1 %}{% set rc.none_a = rc.none_a + _amt -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

{%- set pk = namespace(total=0) -%}
{%- set pk.total = PARK | sum(attribute="amount") -%}

{%- set mz = namespace(bike=0, fork=0) -%}
{%- set mz.bike = MISC | selectattr("kind","equalto","Bike Fuel") | sum(attribute="amount") -%}
{%- set mz.fork = MISC | selectattr("kind","equalto","Forklift") | sum(attribute="amount") -%}
{%- set bike_rows = (MISC | selectattr("kind","equalto","Bike Fuel") | selectattr("amount") | list) -%}
{%- set fork_rows = (MISC | selectattr("kind","equalto","Forklift") | selectattr("amount") | list) -%}

{%- set wl = namespace(wage=0, ot=0, piece=0, comm=0, all=0, loans=0, signed=0) -%}
{%- set wl.wage = WAGES | selectattr("entry_type","equalto","Wage") | sum(attribute="amount") -%}
{%- set wl.ot = WAGES | selectattr("entry_type","equalto","Overtime") | sum(attribute="amount") -%}
{%- set wl.piece = WAGES | selectattr("entry_type","equalto","Piecework") | sum(attribute="amount") -%}
{%- set wl.comm = WAGES | selectattr("entry_type","equalto","Commission") | sum(attribute="amount") -%}
{%- set wl.all = WAGES | sum(attribute="amount") -%}
{%- set wl.loans = LOANS | sum(attribute="amount_issued") -%}
{%- set wl.signed = LOANS | sum(attribute="amount_signed") -%}

{%- set wage_rows = (WAGES | selectattr("recipient") | list) + (WAGES | rejectattr("recipient") | selectattr("amount") | list) -%}
{%- set loan_rows = (LOANS | selectattr("recipient") | list) + (LOANS | rejectattr("recipient") | selectattr("amount_issued") | list) -%}

{#- Week runs SUNDAY -> SATURDAY (7 days), for ALL weeks. Roll week_ending forward to
   its Saturday (new sheets store Sat, historical store Fri) then back to the Sunday. -#}
{%- set _wd = frappe.utils.getdate(doc.week_ending) if doc.week_ending else None -%}
{%- set saturday = frappe.utils.add_days(doc.week_ending, ((5 - _wd.weekday()) % 7)) if _wd else None -%}
{%- set sunday = frappe.utils.add_days(saturday, -6) if saturday else None -%}
{%- set SUN_S = frappe.utils.format_date(sunday, "dd/MM/yyyy") if sunday else "" -%}
{%- set SAT_S = frappe.utils.format_date(saturday, "dd/MM/yyyy") if saturday else "" -%}
{%- set WK = doc.week_no -%}
{%- set FL = doc.float -%}
{%- set CUST = doc.custodian_name or doc.custodian or "" -%}

{#- cumulative loan ledger: every loan up to & incl. this week, all floats -#}
{%- set ledger = namespace(rows=[], issued=0, signed=0, ok=False) -%}
{%- if frappe is defined and frappe.get_all is defined and doc.week_ending -%}
  {%- set _try = namespace(rows=None) -%}
  {%- set _try.rows = frappe.get_all("Petty Cash Loan Entry", filters={"parenttype": "Petty Cash Sheet", "cancelled": 0}, fields=["parent","txn_date","recipient","staff_id","reason","amount_issued","amount_signed","paye"], order_by="txn_date asc, idx asc", limit_page_length=0, ignore_permissions=True) -%}
  {%- if _try.rows is not none -%}
    {%- set _parents = _try.rows | map(attribute="parent") | list -%}
    {%- set _sheets = frappe.get_all("Petty Cash Sheet", filters={"name": ["in", _parents]}, fields=["name","week_ending","float"], limit_page_length=0, ignore_permissions=True) if _parents else [] -%}
    {%- for r in _try.rows -%}
      {%- if (r.recipient or (r.amount_issued or 0) > 0 or (r.amount_signed or 0) > 0) -%}
        {%- set _sh = (_sheets | selectattr("name","equalto", r.parent) | list | first) if _sheets else None -%}
        {%- set _we = _sh.week_ending if _sh else None -%}
        {%- set _fl = _sh.float if _sh else "" -%}
        {%- if _we and _we <= doc.week_ending -%}
          {%- set _cur = (_sh.name == doc.name) -%}
          {%- set ledger.rows = ledger.rows + [{"week_ending": _we, "float": _fl, "txn_date": r.txn_date, "recipient": r.recipient, "staff_id": r.staff_id, "reason": r.reason, "amount_issued": r.amount_issued or 0, "amount_signed": r.amount_signed or 0, "paye": r.paye, "is_current": _cur}] -%}
          {%- set ledger.issued = ledger.issued + (r.amount_issued or 0) -%}
          {%- set ledger.signed = ledger.signed + (r.amount_signed or 0) -%}
          {%- set ledger.ok = True -%}
        {%- endif -%}
      {%- endif -%}
    {%- endfor -%}
    {%- set ledger.rows = ledger.rows | sort(attribute="float") | sort(attribute="week_ending") -%}
  {%- endif -%}
{%- endif -%}

{#- Which logical sheets exist? Count them first, then number them as we emit. -#}
{%- set has_veh = true if (pk.total or bike_rows or fork_rows) else false -%}
{%- set has_wag = true if wage_rows else false -%}
{%- set has_loa = true if loan_rows else false -%}
{%- set has_led = true if (ledger.ok and ledger.rows) else false -%}
{%- set has_emp = true if (not (VOUCH | selectattr("amount") | list) and not pk.total and not bike_rows and not fork_rows and not wage_rows and not loan_rows) else false -%}
{%- set NPAGES = 2 + (1 if has_veh else 0) + (1 if has_wag else 0) + (1 if has_loa else 0) + (1 if has_led else 0) + (1 if has_emp else 0) -%}
{%- set pg = namespace(i=0) -%}

<div class="pcws">
<style>
  /* ---------------------------------------------------------------------
     VCL brand v4.  Blue #2B3990 primary  |  Blue2 #3D4BA0 section bars
     Red #ED1C24 = negatives + OUT header + no-receipt header ONLY
     Amber #B35A00 on #FCE9D2 = warning   |  Green #0B6B3A = money-in
     Purple #5C3D9E = info chip           |  Cream #FFF7E6 = attention
     Calibri throughout. Courier New is reserved for code/field references;
     this document contains none, so it is not used.
     No flexbox: wkhtmltopdf's WebKit has no flexbox -- paired blocks use
     display:table / table-cell.
  --------------------------------------------------------------------- */
  .pcws { font-family: Calibri, Carlito, "Segoe UI", Arial, sans-serif; color:#1C1E2E; font-size:8.5pt; }

  /* width:100% + padding + border must not overflow the page, or the right-hand
     meta is clipped mid-word ("... - Shir") */
  .pcws .title-bar, .pcws .section-h, .pcws .code-legend, .pcws .empty-state { box-sizing:border-box; }

  .pcws .title-bar { background:#2B3990; color:#fff; padding:8px 12px; display:table; width:100%; table-layout:fixed; }
  .pcws .title-bar > div { display:table-cell; vertical-align:middle; }
  .pcws .title-bar > div:first-child { width:50%; font-size:12pt; font-weight:bold; letter-spacing:0.2px; }
  .pcws .title-bar > div:last-child { text-align:right; font-size:8pt; opacity:0.92; }
  .pcws .title-bar .sub { font-size:10.5pt; font-weight:normal; opacity:0.95; }

  .pcws .section-h { background:#3D4BA0; color:#fff; font-weight:bold; padding:5px 12px; font-size:9.5pt; margin-top:9px; }

  /* ---- tables: hairline rules only ---- */
  .pcws table { width:100%; border-collapse:collapse; margin-top:4px; font-size:8.5pt; table-layout:fixed; }
  .pcws th, .pcws td { border:0.5px solid #C7CBDA; padding:3px 5px; vertical-align:middle; word-wrap:break-word; overflow-wrap:break-word; }
  .pcws th { background:#2B3990; color:#fff; font-weight:bold; text-align:center; font-size:8pt; line-height:1.15; }
  .pcws th.sub-h { background:#3D4BA0; font-size:7.2pt; line-height:1.12; word-break:normal; word-wrap:normal; overflow-wrap:normal; }
  .pcws th .sub { display:block; font-weight:normal; font-size:6.8pt; opacity:0.85; margin-top:1px; }
  .pcws td.right, .pcws th.right { text-align:right; }
  .pcws td.center, .pcws th.center { text-align:center; }
  .pcws th.lbl { background:#EEF0F6; color:#2B3990; text-align:left; }
  .pcws td.lbl { background:#F7F8FB; font-weight:bold; text-align:left; color:#1C1E2E; }

  /* dense sheets: voucher register + loan ledger (~38 rows to a page) */
  .pcws table.dense { font-size:7.8pt; }
  .pcws table.dense th, .pcws table.dense td { padding:2.5px 4px; line-height:1.1; }

  /* ---- row precedence: exception/status fill > banding > white ----
     (equal specificity, later rule wins -- keep this order) */
  .pcws tbody tr.zb td { background:#EEF0F6; }
  .pcws tbody tr td.in-cell { background:#E6F4EA; color:#0B6B3A; font-weight:bold; text-align:right; }
  .pcws tbody tr.cw td { background:#FFF7E6; }                     /* new this week */
  .pcws tbody tr.xr td { background:#FCE9D2; color:#B35A00; }      /* spend, no PC + no ETR */
  .pcws tbody tr.xr td:first-child { border-left:2.5px solid #B35A00; }
  .pcws tbody tr.tot td { background:#2B3990; color:#fff; font-weight:bold; border-color:#2B3990; }
  .pcws tbody tr.tot td.in-cell { background:#0B6B3A; color:#fff; border-color:#0B6B3A; }
  .pcws tbody tr.tot .neg { color:#FFD3D5; }

  /* attention figures (cream), never blue-on-red */
  .pcws td.attn { background:#FFF7E6; font-weight:bold; color:#2B3990; }
  .pcws td.attn-l { background:#FFF7E6; font-weight:bold; color:#2B3990; text-align:left; }

  /* money */
  .pcws .neg { color:#ED1C24; font-weight:bold; }
  .pcws td.pct { background:#EEF0F6; font-weight:bold; color:#1C1E2E; }

  /* header accents -- red is state, never decoration */
  .pcws th.out-h { background:#ED1C24; border-color:#ED1C24; }
  .pcws th.in-h  { background:#0B6B3A; border-color:#0B6B3A; }
  .pcws th.none-h { background:#ED1C24; border-color:#ED1C24; }
  .pcws td.none-c { background:#FCE9D2; color:#B35A00; font-weight:bold; }

  /* wages type chip: C (Commission) is purple to separate it from W (Wage) */
  .pcws .chip { display:inline-block; width:15px; padding:0 2px; border-radius:2px; background:#2B3990; color:#fff; font-size:6.8pt; font-weight:bold; line-height:12px; text-align:center; }
  .pcws .chip-c { background:#5C3D9E; }

  .pcws .code-legend { background:#F7F8FB; border:0.5px solid #C7CBDA; padding:4px 10px; font-size:7.5pt; margin-top:4px; }
  .pcws .code-legend .code { font-weight:bold; color:#2B3990; }
  .pcws .code-legend .sep { color:#C7CBDA; margin:0 5px; }
  .pcws .code-legend .swatch { display:inline-block; width:11px; height:9px; background:#FCE9D2; border:0.5px solid #B35A00; vertical-align:-1px; margin:0 3px; }

  /* paired side-by-side blocks -- display:table, 14px gutter (no flexbox) */
  .pcws .two { display:table; width:100%; table-layout:fixed; margin-top:4px; }
  .pcws .two > div { display:table-cell; width:50%; vertical-align:top; }
  .pcws .two > div:first-child { padding-right:7px; }
  .pcws .two > div:last-child { padding-left:7px; }
  .pcws .two h3 { margin:4px 0 0 0; color:#3D4BA0; font-size:9.5pt; }

  .pcws .note { margin-top:6px; font-size:7.5pt; color:#4A4F63; }
  .pcws .note .flag { color:#ED1C24; font-weight:bold; }
  .pcws .empty-state { padding:24px; text-align:center; color:#8A8F9E; font-style:italic; font-size:9pt; border:0.5px dashed #C7CBDA; margin-top:6px; }

  /* running footer, one per logical sheet */
  .pcws .pfoot { margin-top:7px; border-top:0.5px solid #C7CBDA; padding-top:3px; }
  .pcws .pfoot table { margin:0; font-size:7pt; }
  .pcws .pfoot td { border:0; padding:0; color:#6B7280; }
  .pcws .pfoot td.l { text-align:left; }
  .pcws .pfoot td.r { text-align:right; }

  .pcws .page-break { page-break-before: always; }

  @media print {
    .pcws table { page-break-inside:auto; }
    .pcws thead { display:table-header-group; }
    .pcws tfoot { display:table-row-group; }
    .pcws tr { page-break-inside:avoid; page-break-after:auto; }
    .pcws table.meta-strip, .pcws table.receipt-tracker, .pcws table.sumtbl,
    .pcws .two > div, .pcws .code-legend, .pcws .pfoot { page-break-inside:avoid; }
    @page { size: A4 landscape; margin: 6mm; }
  }
</style>

{#- ============ SHEET 1: RECONCILIATION & SUMMARY COVER ============ -#}
{%- set pg.i = pg.i + 1 -%}
<div class="title-bar">
  <div>VIMIT CONVERTERS LIMITED &nbsp;|&nbsp; <span class="sub">WEEKLY PETTY CASH &mdash; RECONCILIATION &amp; SUMMARY</span></div>
  <div>COVER SHEET &middot; Wk {{ WK }} &middot; {{ FL }} Float &middot; {{ SUN_S }} &ndash; {{ SAT_S }} &middot; {{ CUST }}</div>
</div>

<table class="cover-meta">
  <colgroup><col style="width:12%"><col style="width:22%"><col style="width:36%"><col style="width:30%"></colgroup>
  <thead>
    <tr><th>WEEK NO</th><th>WEEK (SUN&ndash;SAT)</th><th>CUSTODIAN</th><th>OPENING BALANCE (KES)</th></tr>
  </thead>
  <tbody>
    <tr>
      <td class="center">{{ WK }}</td>
      <td>{{ SUN_S }} &ndash; {{ SAT_S }}</td>
      <td>{{ CUST }}</td>
      <td class="right">{{ m(doc.opening_balance or 0) }}</td>
    </tr>
  </tbody>
</table>

<div class="section-h">CATEGORY BREAKDOWN (from Voucher Register)</div>
<table class="sumtbl">
  <colgroup><col style="width:20%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:9%"><col style="width:17%"></colgroup>
  <thead>
    <tr>
      <th class="lbl">VOUCHER REGISTER &mdash; BY CATEGORY</th>
      {% for c in CAT %}<th>{{ CAT_FULL[c][0] }}{% if CAT_FULL[c][1] %}<br>{{ CAT_FULL[c][1] }}{% endif %}</th>{% endfor %}
      <th>TOTAL</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="lbl">Cash OUT (KES)</td>
      {% for c in CAT %}{% set catout = VOUCH | rejectattr("cash_in") | selectattr("category","equalto",c) | sum(attribute="amount") %}<td class="right">{{ m(catout) }}</td>{% endfor %}
      <td class="right attn">{{ m(s.voucher_out) }}</td>
    </tr>
    <tr>
      <td class="lbl">Cash IN (KES) &mdash; refunds</td>
      <td colspan="7"></td>
      <td class="in-cell">{{ m(s.cat_in) }}</td>
    </tr>
    <tr>
      <td class="lbl">Vouchers / Receipts</td>
      <td colspan="7" class="right">PC slips: <strong>{{ s.pc }}</strong> &nbsp;&middot;&nbsp; ETR receipts: <strong>{{ s.etr }}</strong> &nbsp;&middot;&nbsp; rows used: <strong>{{ s.used }}</strong></td>
      <td></td>
    </tr>
    <tr>
      <td class="lbl">% of Voucher Spend</td>
      {% for c in CAT %}{% set catout = VOUCH | rejectattr("cash_in") | selectattr("category","equalto",c) | sum(attribute="amount") %}<td class="pct center">{% if s.voucher_out and s.voucher_out > 0 %}{{ ((catout / s.voucher_out) * 100)|round(0)|int }}%{% else %}&mdash;{% endif %}</td>{% endfor %}
      <td class="pct center" style="color:#2B3990">100%</td>
    </tr>
  </tbody>
</table>

<div class="section-h">VEHICLE BREAKDOWN (from Vehicle Sheet)</div>
<table class="sumtbl">
  <colgroup><col style="width:22%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:11%"><col style="width:12%"></colgroup>
  <thead>
    <tr>
      <th class="lbl">VEHICLE SHEET &mdash; BY VEHICLE</th>
      {% for vh in VEHICLES %}<th>{{ vh }}</th>{% endfor %}
      <th>BIKE</th>
      <th>FORKLIFT</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td class="lbl">Weekly Spend (KES)</td>
      {% for vh in VEHICLES %}{% set vtot = PARK | selectattr("vehicle","equalto",vh) | sum(attribute="amount") %}<td class="right">{{ m(vtot) }}</td>{% endfor %}
      <td class="right">{{ m(mz.bike) }}</td>
      <td class="right">{{ m(mz.fork) }}</td>
    </tr>
  </tbody>
</table>

<div class="section-h">END OF WEEK RECONCILIATION</div>
<div class="two">
  <div>
    <h3>CASH MOVEMENT</h3>
    <table>
      <colgroup><col style="width:65%"><col style="width:35%"></colgroup>
      <tbody>
        <tr><td class="lbl">A. Opening Balance (start of week)</td><td class="right">{{ m(doc.opening_balance or 0) }}</td></tr>
        <tr><td class="lbl">B. Grand Total Cash OUT (vouchers + vehicle + bike + forklift + wages + loans + commission)</td><td class="right">{{ m(doc.total_out or 0) }}</td></tr>
        <tr><td class="lbl">C. Total Cash IN (refunds)</td><td class="right">{{ m(doc.total_in or 0) }}</td></tr>
        <tr><td class="attn-l">D. EXPECTED CLOSING = A &minus; B + C</td><td class="attn right">{{ m(doc.expected_close or 0) }}</td></tr>
      </tbody>
    </table>
  </div>
  <div>
    <h3>PHYSICAL RECONCILIATION</h3>
    <table>
      <colgroup><col style="width:65%"><col style="width:35%"></colgroup>
      <tbody>
        <tr><td class="lbl">E. Physical Cash Count (end of week)</td><td class="right">{{ m(doc.cash_count_end or 0) }}</td></tr>
